import React, { useRef, useLayoutEffect } from "react";
import atomize from "@quarkly/atomize"; // Put your HTML here:

const customHtml = `<iframe
title="Latest Theory Video"
width="100%"
height="100%"
src="https://www.youtube-nocookie.com/embed/videoseries?si=cXmjXl8NjUTO4qhN&amp;controls=0&amp;list=PLJmTEYXxCKpnL_hVZCVMU4OP77dU5Q6IH"
title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen>
</iframe>`;

const VideoEmbed = ({
	children,
	...props
}) => {
	const ref = useRef(null);
	useLayoutEffect(() => {
		ref.current.innerHTML = customHtml;
	}, []);
	return <div {...props} ref={ref} />;
};

export default atomize(VideoEmbed)({
	name: "VideoEmbed",
	normalize: true,
	mixins: true
});